function showAlert(form,message,type){let box=form.parentElement.querySelector(".alert");box||(box=document.createElement("div"),form.parentElement.insertBefore(box,form)),box.className=`alert alert-${type}`,box.textContent=message}document.addEventListener("submit",async e=>{const form=e.target;if("FORM"!==form.tagName||form.hasAttribute("data-no-ajax"))return;let data;e.preventDefault();try{const res=await fetch(form.action,{method:form.method||"POST",headers:{"X-Requested-With":"XMLHttpRequest"},body:new FormData(form)});data=await res.json()}catch(err){return console.error("Form submission failed:",err),void showAlert(form,"Something went wrong. Please try again.","danger")}data.success?window.location.href=data.redirect||"/":showAlert(form,data.message,data.type||"danger")});